// End-to-end smoke test: two bot clients play a full cycle.
// lobby -> charselect -> mapselect -> battle -> (one bot walks off repeatedly) -> victory -> charselect
const WebSocket = require('ws');

const URL = 'ws://localhost:3000';
const results = { phases: new Set(), kos: 0, snaps: 0, winner: null, hits: 0 };
let failed = false;

function fail(msg) { console.error('FAIL:', msg); failed = true; finish(); }

function bot(name, isHost) {
  const ws = new WebSocket(URL);
  const state = { id: null, phase: null };
  ws.on('open', () => ws.send(JSON.stringify({ type: 'join', name })));
  ws.on('message', (raw) => {
    const msg = JSON.parse(raw);
    if (msg.type === 'welcome') state.id = msg.id;
    if (msg.type === 'state') {
      if (state.phase !== msg.phase) {
        state.phase = msg.phase;
        results.phases.add(msg.phase);
        if (isHost) console.log('phase ->', msg.phase);
        if (msg.phase === 'lobby' && isHost) {
          setTimeout(() => ws.send(JSON.stringify({ type: 'startSelect' })), 400);
        }
        if (msg.phase === 'charselect') {
          setTimeout(() => {
            ws.send(JSON.stringify({ type: 'pickChar', char: isHost ? 'blaze' : 'titan' }));
            setTimeout(() => ws.send(JSON.stringify({ type: 'ready', ready: true })), 150);
          }, 200);
        }
        if (msg.phase === 'mapselect') {
          setTimeout(() => ws.send(JSON.stringify({ type: 'voteMap', map: 'skylands' })), 200);
        }
        if (msg.phase === 'victory') {
          results.winner = msg.winnerId;
          console.log('winner id:', msg.winnerId);
          setTimeout(finish, 500);
        }
      }
    }
    if (msg.type === 'snap') {
      results.snaps++;
      if (msg.countdown === 0 && !isHost) {
        // non-host bot suicides: hold left to run off the stage
        ws.send(JSON.stringify({ type: 'input', left: 1 }));
      }
      if (msg.countdown === 0 && isHost) {
        // host attacks occasionally to exercise hit logic
        const t = Date.now() % 1000;
        ws.send(JSON.stringify({ type: 'input', right: t < 300 ? 1 : 0, jab: t > 500 && t < 600 ? 1 : 0 }));
      }
    }
    if (msg.type === 'event') {
      if (msg.kind === 'ko') { results.kos++; console.log('KO! total:', results.kos); }
      if (msg.kind === 'hit') results.hits++;
    }
  });
  ws.on('error', (e) => fail('ws error: ' + e.message));
  return ws;
}

const b1 = bot('HostBot', true);
setTimeout(() => bot('FallBot', false), 300);

const timeout = setTimeout(() => fail('timed out after 40s; phases seen: ' + [...results.phases].join(',')), 40000);

function finish() {
  clearTimeout(timeout);
  const need = ['lobby', 'charselect', 'mapselect', 'battle', 'victory'];
  const missing = need.filter(p => !results.phases.has(p));
  console.log('---');
  console.log('phases:', [...results.phases].join(', '));
  console.log('snapshots received:', results.snaps);
  console.log('KOs:', results.kos, ' hits landed:', results.hits);
  if (!failed && missing.length === 0 && results.kos >= 3 && results.snaps > 50 && results.winner) {
    console.log('SMOKE TEST PASSED');
    process.exit(0);
  } else {
    console.log('SMOKE TEST FAILED', missing.length ? '(missing phases: ' + missing.join(',') + ')' : '');
    process.exit(1);
  }
}
